"""Regression checks for raw secret-detection patterns and compile-time warnings.

No secrets, network calls, cloud credentials or changes to provider SDKs.
"""
import re
import warnings
from pathlib import Path

from ScoutSuite.providers.utils import secret_patterns


_SOURCE = Path(__file__).resolve().parents[1] / "ScoutSuite" / "providers" / "utils.py"


def test_provider_utils_compiles_without_python_deprecation_or_syntax_warnings():
    # The original 50 warnings were generated by invalid Python *string*
    # escapes. Inspect compilation rather than suppressing warning categories.
    with warnings.catch_warnings():
        warnings.simplefilter("error", DeprecationWarning)
        warnings.simplefilter("error", SyntaxWarning)
        compile(_SOURCE.read_text(encoding="utf-8"), str(_SOURCE), "exec")


def test_all_secret_patterns_still_compile_and_keep_original_catalog():
    assert len(secret_patterns) == 87
    assert all(isinstance(value, re.Pattern) for value in secret_patterns.values())
    assert all(isinstance(name, str) and name for name in secret_patterns)


def test_synthetic_secret_patterns_continue_matching_expected_formats():
    # Deliberately synthetic tokens only; never print or log matched content.
    samples = {
        "AWS key": "AKIA" + "0" * 16,
        "GitHub Personal Access Token": "ghp_" + "A" * 36,
        "GitHub Refresh Token": "ghr_" + "A" * 76,
        "GitLab Personal Access Token": "glpat-" + "A" * 20,
        "Discord client ID": 'discord_token="' + "0" * 18 + '"',
        "Doppler API token": '"dp.pt.' + "a" * 43 + '"',
        "Dynatrace API token": '"dt0c01.' + "a" * 24 + "." + "b" * 64 + '"',
        "Slack token": "xoxb-" + "A" * 20,
        "Generic Password": "sample_password_key",
        "Generic Secret": "sample_secret_key",
    }
    for name, text in samples.items():
        assert secret_patterns[name].search(text) is not None, name
    assert secret_patterns["AWS key"].search("AKIA" + "0" * 15) is None
    assert secret_patterns["GitHub Personal Access Token"].search(
        "ghp_" + "A" * 35) is None


def test_regex_literal_fix_does_not_modify_unrelated_runtime_functions():
    source = _SOURCE.read_text(encoding="utf-8")
    block = source.split("secret_patterns = {", 1)[1].split("\ndef is_secret", 1)[0]
    assert block.count("re.compile(") == 87
    # Every detector has a raw Python regex literal, preserving regex escapes.
    assert block.count('re.compile(r"') == 87
